export const DEFAULT_API_GROUP_NAME = 'API Reference';
export const DEFAULT_WEBSOCKETS_GROUP_NAME = 'Websockets';
const tagKeys = new WeakMap();
export function findNavGroup(nav, groupName = DEFAULT_API_GROUP_NAME, tagKey) {
    const group = nav.find((fileOrGroup) => typeof fileOrGroup === 'object' &&
        'group' in fileOrGroup &&
        fileOrGroup.group === groupName &&
        (tagKey === undefined || tagKeys.get(fileOrGroup) === tagKey));
    if (group === undefined || typeof group !== 'object' || !('pages' in group)) {
        const newGroup = {
            group: groupName,
            pages: [],
        };
        if (tagKey !== undefined)
            tagKeys.set(newGroup, tagKey);
        nav.push(newGroup);
        return newGroup.pages;
    }
    if (Array.isArray(group.pages)) {
        return group.pages;
    }
    return [];
}
